import { readFileSync } from 'fs';
import pg from './node_modules/pg/lib/index.js';
const { Pool } = pg;
const rawUrl = String(process.env.DATABASE_URL||'');
const url = (() => { try { const u = new URL(rawUrl); ['sslmode','sslcert','sslkey','sslrootcert','sslpassword'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return rawUrl; } })();
let ssl; try { ssl = { rejectUnauthorized: true, ca: readFileSync('./certs/rds-ca-bundle.pem') }; } catch { ssl = { rejectUnauthorized: false }; }
const pool = new Pool({ connectionString: url, ssl, max: 1 });
const c = await pool.connect();
let pass = true;

// 1. Migrations applied
const { rows: migs } = await c.query("SELECT id FROM schema_migrations WHERE id IN ('021_create_municipalities','022_add_municipality_fk_to_units','023_create_cid10','024_create_ciap2') ORDER BY id");
const migIds = migs.map(r=>r.id);
console.log('MIGRATIONS: ' + migIds.join(','));
if (migIds.length !== 4) { console.error('FAIL migrations: expected 4, got ' + migIds.length); pass=false; }

// 2. Table counts
const { rows: munCnt } = await c.query('SELECT COUNT(*)::int AS n FROM municipalities');
const { rows: cid10Cnt } = await c.query('SELECT COUNT(*)::int AS n FROM cid10');
const { rows: ciap2Cnt } = await c.query('SELECT COUNT(*)::int AS n FROM ciap2');
console.log('municipalities COUNT=' + munCnt[0].n + ' (min=5570: ' + (munCnt[0].n>=5570?'PASS':'FAIL') + ')');
console.log('cid10 COUNT=' + cid10Cnt[0].n + ' (min=14000: ' + (cid10Cnt[0].n>=14000?'PASS':'PENDING-needs-DATASUS-seed') + ')');
console.log('ciap2 COUNT=' + ciap2Cnt[0].n + ' (min=650: ' + (ciap2Cnt[0].n>=650?'PASS':'FAIL') + ')');
if (munCnt[0].n < 5570) { console.error('FAIL municipalities count'); pass=false; }
if (ciap2Cnt[0].n < 650) { console.error('FAIL ciap2 count'); pass=false; }

// 3. Known codes
const { rows: ibge } = await c.query("SELECT name, uf FROM municipalities WHERE ibge_code = '3534401'");
console.log('3534401 = ' + (ibge[0] ? ibge[0].name+'/'+ibge[0].uf : 'NOT FOUND'));
const { rows: r81 } = await c.query("SELECT description FROM ciap2 WHERE code = 'R81'");
console.log('CIAP2 R81 = ' + (r81[0] ? r81[0].description : 'NOT FOUND'));

// 4. FK constraint on app_units
const { rows: fk } = await c.query("SELECT constraint_name, constraint_type FROM information_schema.table_constraints WHERE table_name = 'app_units' AND constraint_name = 'fk_app_units_municipality_id'");
console.log('FK fk_app_units_municipality_id: ' + (fk.length > 0 ? 'EXISTS' : 'MISSING'));
if (fk.length === 0) { console.error('FAIL FK not applied'); pass=false; }

// 5. No app_units with empty municipality_id
const { rows: empty } = await c.query("SELECT COUNT(*)::int AS n FROM app_units WHERE municipality_id = '' OR municipality_id IS NULL");
console.log('app_units empty municipality_id: ' + empty[0].n + ' (expected=0)');
if (empty[0].n > 0) { console.error('FAIL: empty municipality_id in app_units'); pass=false; }

// 6. Idempotency check: seed CIAP-2 safe to re-run
const { rows: ciap2Before } = await c.query('SELECT COUNT(*)::int AS n FROM ciap2');
console.log('ciap2 before re-check: ' + ciap2Before[0].n);

console.log(pass ? 'SMOKE-8B-FINAL PASS' : 'SMOKE-8B-FINAL FAIL');
c.release(); await pool.end();
